diff --git a/wradlib/georef/polar.py b/wradlib/georef/polar.py
index f021e83..9ffea57 100644
--- a/wradlib/georef/polar.py
+++ b/wradlib/georef/polar.py
@@ -1136,9 +1136,8 @@ def georeference(obj, **kwargs):
     cf_by_axis = {c["axis"]: c for c in cf_coords}
     x_attrs = cf_by_axis.get("X")
     y_attrs = cf_by_axis.get("Y")
-    unit = x_attrs["units"]
-    z_attrs = {"standard_name": "height_above_ground", "units": unit}
-    gr_attrs = {"standard_name": "distance_from_radar", "units": unit}
+    z_attrs = {"standard_name": "height_above_ground", "units": "meters"}
+    gr_attrs = {"standard_name": "distance_from_radar", "units": "meters"}
     obj.coords["x"] = (dimlist, xyz[..., 0], x_attrs)
     obj.coords["y"] = (dimlist, xyz[..., 1], y_attrs)
     obj.coords["z"] = (dimlist, xyz[..., 2], z_attrs)

diff --git a/xarray/core/indexes.py b/xarray/core/indexes.py
index 664afc8..969970d 100644
--- a/xarray/core/indexes.py
+++ b/xarray/core/indexes.py
@@ -781,7 +781,7 @@ class PandasIndex(Index):
             if len(indexes_coord_dtypes) == 1:
                 coord_dtype = next(iter(indexes_coord_dtypes))
             else:
-                coord_dtype = np.result_type(*indexes_coord_dtypes)
+                coord_dtype = None

         return cls(new_pd_index, dim=dim, coord_dtype=coord_dtype)

@@ -904,7 +904,7 @@ class PandasIndex(Index):
             # how = "inner"
             index = self.index.intersection(other.index)

-        coord_dtype = np.result_type(self.coord_dtype, other.coord_dtype)
+        coord_dtype = None
         return type(self)(index, self.dim, coord_dtype=coord_dtype)

     def reindex_like(
@@ -1081,11 +1081,7 @@ class PandasMultiIndex(PandasIndex):
         if not indexes:
             level_coords_dtype = None
         else:
-            level_coords_dtype = {}
-            for name in indexes[0].level_coords_dtype:
-                level_coords_dtype[name] = np.result_type(
-                    *[idx.level_coords_dtype[name] for idx in indexes]
-                )
+            level_coords_dtype = None

         return cls(new_pd_index, dim=dim, level_coords_dtype=level_coords_dtype)

@@ -1449,10 +1445,7 @@ class PandasMultiIndex(PandasIndex):
             # how = "inner"
             index = self.index.intersection(other.index)

-        level_coords_dtype = {
-            k: np.result_type(lvl_dtype, other.level_coords_dtype[k])
-            for k, lvl_dtype in self.level_coords_dtype.items()
-        }
+        level_coords_dtype = None

         return type(self)(index, self.dim, level_coords_dtype=level_coords_dtype)
